with recent_payments as (select * from payments where paid_at < '2025-10-30'), summary as (select date_trunc('MONTH', paid_at) paid_month, method, sum(case when method = 'promptpay' then 1 else 0 end) promptpay_count, sum(amount) total_amount from recent_payments group by date_trunc('MONTH', paid_at), method) select paid_month, method, promptpay_count from summary order by promptpay_count desc, method;
